"""Component catalogues: airfoils, motors, propellers, cells, ESCs.

IMPORTANT
---------
The numbers below are *representative* values for real, commonly-available
DBF-class hardware.  They are good enough to rank configurations, and they are
NOT a substitute for the manufacturer data sheet or your own dyno / thrust-stand
run.  Before you cut aluminium, replace the entries you actually intend to buy
with measured values (see `load_motors_csv` / `load_props_csv`).

Every record carries `source` so you can see what still needs verifying.
"""
from __future__ import annotations

import bisect
import csv
import json
import math
import os
from dataclasses import dataclass, replace
from typing import Any, Dict, List, Optional, Tuple

from .numerics import PCHIP
from .units import IN2M


# ==========================================================================
# Airfoils
# ==========================================================================
@dataclass(frozen=True)
class Airfoil:
    name: str
    cl_max_2d: float        # section clmax at re_ref
    cd_min: float           # section minimum profile drag at re_ref
    cl_at_cd_min: float
    k_drag: float           # cd = cd_min + k*(cl-cl_opt)^2
    cl_break: float         # cl beyond which drag rises sharply
    t_over_c: float
    cm_ac: float
    re_ref: float = 300_000.0
    note: str = ""
    # The section polar itself, as (cl, cd) pairs at re_ref with cl
    # increasing, up to CLmax.  When present the model's profile drag is
    # read from it (monotone cubic interpolation) instead of from the
    # parametric bucket above.  The parametric fields are then a fitted
    # summary of the same data, kept for the catalogue display and as the
    # fallback for airfoils entered by hand, which carry no table.
    #
    # Why both: a symmetric parabola cannot reproduce the lopsided polar
    # of a highly cambered section - flat across a wide low-drag range,
    # then a steep rise.  Fitted to the same XFOIL data it was off by more
    # than 50% for the DAE, MH11x, E423 and S12xx sections, overstating
    # their cruise drag and quietly biasing any comparison against them.
    polar: Tuple[Tuple[float, float], ...] = ()
    # The section's zero-lift angle, deg, and lift-curve slope, per radian,
    # from the same XFOIL polar (a straight-line fit over -2 to +6 deg,
    # m109).  None for a hand-entered section: the model then estimates the
    # angle from cm_ac and takes 2 pi for the slope.
    alpha_l0_deg: Optional[float] = None
    cl_alpha_per_rad: Optional[float] = None

    def __post_init__(self) -> None:
        if self.polar:
            xs = [p[0] for p in self.polar]
            ys = [p[1] for p in self.polar]
            if any(b <= a for a, b in zip(xs, xs[1:])):
                raise ValueError("%s polar: cl must be strictly increasing"
                                 % self.name)
            object.__setattr__(self, "_table", PCHIP(xs, ys))

    def cd_excess(self, cl: float) -> float:
        """Section profile drag above cd_min at lift coefficient `cl`.

        This is the lift-dependent part of the profile drag; cd_min itself
        is Reynolds-corrected and carried in the parasite drag.  With a
        polar table: read from the table, continued below it along the
        fitted bucket and above it (past CLmax) with the stall rise.
        Without one: the parametric bucket plus stall rise.
        """
        if self.polar:
            lo, hi = self.polar[0][0], self.polar[-1][0]
            if cl < lo:
                base = self.polar[0][1] - self.cd_min
                return max(base, 0.0) + self.k_drag * (lo - cl) ** 2
            if cl > hi:
                d = cl - hi
                base = self.polar[-1][1] - self.cd_min
                return max(base, 0.0) + 0.085 * d * d + 0.25 * d ** 3
            return max(self._table(cl) - self.cd_min, 0.0)
        cd = self.k_drag * (cl - self.cl_at_cd_min) ** 2
        over = cl - self.cl_break
        if over > 0.0:
            cd += 0.085 * over ** 2 + 0.25 * over ** 3
        return cd


# --------------------------------------------------------------------------
# The catalogue: 32 sections, every one from airfoiltools.com (retrieved
# 2026-09-27).  One source and one method, so the sections compare fairly.
# 30 were chosen by the screen described below; E214 and E423 were added
# afterwards at the team's request, from the same screen's data.
#
# Data: the site's XFOIL polar at Re 500,000, Ncrit 9 - the middle of the
# 395k-678k band this aircraft flies on its mean chord, stall to top speed.
# re_ref is therefore 500k and the Reynolds correction to flight is small.
#
#   polar            the (cl, cd) table itself - what the model reads
#   cl_max_2d        highest cl in the polar
#   cd_min           lowest cd in the polar
#   cl_at_cd_min, k_drag, cl_break
#                    the parametric bucket least-squares fitted to the polar
#                    over the cl range flown (to 0.9 CLmax): a summary for the
#                    catalogue display, and the form used for hand entries
#   cm_ac            mean cm over alpha -2..+4 deg
#   t_over_c         from the site's section data
#
# XFOIL assumes a smooth section.  Its minimum drag here is 22-53% below the
# previous catalogue's (unsourced) values at the same Reynolds number, while
# CLmax mostly agrees to within 8%.  A built, covered wing has more drag than
# XFOIL predicts; that allowance is BuildStandard.profile_drag_factor.
#
# Selection: 66 candidates were screened in this model - span at the limit,
# taper 0.45, AR 5.0-7.0, the two strongest propulsion sets - and ranked on
# total mission score.  23 are the top of that ranking, excluding sections
# under 7% thick (no room for a spar in a heavy-lift wing: S1091, AG26,
# S1010, GOE417A).  The other 7 are kept because saved designs and the tests
# name them: E205, SA7038, SD7062, MH32, S1223, AG35, CLARKY.  S1218 from the
# previous catalogue is not on the site.  The whole field sits within 0.3
# points of the leader, so treat neighbours in the ranking as ties.
# --------------------------------------------------------------------------
# Section polars: pre-stall (cl, cd) at Re 500,000, thinned to about
# 0.04 in cl.  Read by the model through Airfoil.cd_excess.
