# ==========================================================================
# Motors (brushless outrunners)
# ==========================================================================
@dataclass(frozen=True)
class Motor:
    key: str
    name: str
    kv: float               # rpm per volt, no load
    rm: float               # ohm, effective line resistance used by the model
    i0: float               # A, no-load current
    mass_kg: float
    i_max_a: float          # manufacturer continuous current
    p_max_w: float          # manufacturer continuous power
    shaft_mm: float
    source: str = "catalogue estimate - VERIFY"
    # Highest LiPo cell count the maker rates the motor for.  6 when the
    # maker publishes nothing - the conservative reading.  A pack with more
    # cells is rejected: the model's current and power limits do not
    # capture the winding insulation or the rotor's speed limit.
    max_cells: int = 6
    # The voltage the maker measured the no-load current at: 10 V for most,
    # 8.4 V (2S) for Hacker.  With Kv it fixes the speed the quoted I0
    # belongs to (i0_at).
    i0_volts: float = 10.0

    def i0_at(self, rev_s: float, speed_share: float) -> float:
        """No-load current, A, at shaft speed `rev_s` (rev/s).

        The maker's I0 holds at its test speed, Kv x i0_volts; the
        eddy-current share of it grows in proportion to speed
        (BuildStandard.i0_speed_share)."""
        n_test = max(self.kv * self.i0_volts / 60.0, 1e-6)
        s = min(max(speed_share, 0.0), 1.0)
        return self.i0 * (1.0 - s + s * max(rev_s, 0.0) / n_test)


# --------------------------------------------------------------------------
# Motors: 45 - 38 searched and 7 retired (RETIRED) - after the 2026-09-29
# pruning study (results/catalogue_prune_2026-09-29) cut 84 of 129.  Every
# motor was flown with its own best packs and with the best designs' packs
# at every motor count (1-4); a motor stays if, at some count, it is among
# the 8 best, within 2% of the best, or among the 2 best on packs of its
# voltage band - scored against the field estimates or the way the final
# ranking scores (each mission counted equally), whichever keeps it.
# decisions.csv there gives the reason for every entry.
#
# The first 30 (below), every value from the maker's own page (retrieved
# 2026-09-27) - Hacker, KDE Direct, SunnySky, Neu, Scorpion, T-Motor.  Each
# entry's `source` names the page and the rating basis.
#
# The makers do not rate on a common basis, and that matters here: the
# model treats i_max_a / p_max_w as hard limits at full throttle, but a
# Mission 2 is ~250-300 s near full power.
#   Scorpion        continuous
#   KDE, T-Motor    180 s
#   SunnySky        30 s
#   Hacker          15 s maximum POWER only; current is derived as P / 22.2 V
#   Neu             "continuous watts"; current = min(saturation, W / 22.2 V)
# So a SunnySky or Hacker motor is being held to a looser limit than a
# Scorpion one.  Treat their margins with more suspicion.
# No-load current is quoted at 8.4 V (Hacker) or 10 V (the rest).
# Neu rounds Rm to 0.01 ohm on its site - one significant figure for the
# low-resistance windings.  shaft_mm 0 = not published by the maker.
#
# Selection: 292 candidates in this aircraft's class (120-800 g, 150-1000
# Kv, 0.5-6 kW) were screened in this model: every propeller, motor count
# and full-energy (>= 86 Wh) battery setup, rated in the DENSEST expected
# air (the Tucson morning preset); each motor's best three single- and
# twin-motor setups then flown on the recommended airframe, ranked on total
# mission score.  At most two windings per motor family.  Two guards on the
# scraped data: a page whose Kv disagrees with its own product name is
# rejected (Hacker's A40-16S kv1000 page carries the A40-14L kv355 table),
# and identical listings are merged.
#
# The previous catalogue was unsourced, and wrong in places that mattered:
# "Cobra C-4120/12 465KV" does not exist (the C-4120/12 is 850 Kv); the
# Scorpion SII-4025-330 was 500 g / 0.028 ohm against a real 353 g / 0.037;
# the T-Motor AT4125-540 was 0.038 ohm against a real 0.014; the SunnySky
# X4112S-400 was 300 g against a real ~188 g, and SunnySky does not publish
# that winding at all.  The Scorpion SII-4020-420 is discontinued.
# --------------------------------------------------------------------------
