# Highest rated LiPo cell count, from the same maker pages (retrieved
# 2026-09-27).  SunnySky, KDE, Scorpion and T-Motor state it; Neu states a
# maximum voltage (its speed limit, max rpm / Kv), converted here at 4.2 V
# per charged cell; Hacker gives it in the description or, for the Turnado
# V3, as a 25,000 rpm limit (14S) read with its V4 twin's 10-12S advice.
# The Hacker A40-14L and A50-16S pages give nothing, so they keep the
# conservative 6S - VERIFY with Hacker before flying them higher.
_MAX_CELLS = {
    "SUNNYSKY_X4125_V3_420": 6,
    "SUNNYSKY_X4120_V3_480": 6,
    "SUNNYSKY_X3120_V3_585": 6,
    "SUNNYSKY_X4110S_400": 6,
    "HACKER_A60_6XS_V4_370": 12, "HACKER_A50_14L_TURNADO_V4_400": 12,
    "HACKER_A50_14L_TURNADO_V3_400": 12, "HACKER_A40_14L_V4_355": 6,
    "HACKER_A50_16S_V4_365": 6,
    "NEU_6521_3P5_362": 7,      # 33 V
    "NEU_6530_3_295": 9,        # 41 V
    "NEU_3825_5P5_348": 8,      # 34 V
    "NEU_3825_5_383": 7,        # 31 V
    "NEU_4625_5P5_260": 10,     # 46 V
    "KDE_700XF_535": 14,
    "SCORPION_SII_4025_330": 8, "SCORPION_SII_4025_440": 7,
    "SCORPION_SII_4035_250": 12,
    "TMOTOR_AT4130_300": 12, "TMOTOR_AT4125_540": 6,
}
MOTORS = {k: replace(m, max_cells=_MAX_CELLS.get(k, 6))
          for k, m in MOTORS.items()}

# --------------------------------------------------------------------------
# Motors for 1-4 motor designs, researched 2026-09-29 from the makers' own
# pages (Scorpion, T-Motor, Cobra, KDE Direct, Hacker, SunnySky, Dualsky,
# AXI): 99 went in, and the pruning study the same day kept the ones below
# (no Dualsky among them).  Every entry was checked against physics before
# it went in:
#   * efficiency at the rated current, (1 - I0/I)(1 - I Rm/V), at max cells
#     x 3.7 V: 0.85-0.94 for every motor kept;
#   * copper loss at the rated current, I^2 Rm / mass: under 0.9 W/g;
#   * power density: 2.8-7.4 W/g, consistent with each maker's basis;
#   * motor constant Km = Kt/sqrt(Rm) against mass: every motor sits
#     within its family's trend (Km / m^0.9 = 0.28-0.48).
# Left out, with the reason: T-Motor AT2814 KV900 and AT2826 KV1100 (the
# published Ri are typos - they fail every check); Scorpion SII-4035-450
# (its Rm does not fit its sibling windings); Cobra C-4120/20 (page, chart
# and dealer disagree on Rm and I0); all E-flite (2006 revisions, Rm only
# to 0.01 ohm, which is +-30-50% on these windings).
# Rating bases differ, and the model holds every motor to its figure as a
# hard limit, with the winding-temperature model on top:
#   Scorpion, Cobra   "max continuous", no duration (Scorpion's own charts
#                     run past it); Cobra lists Rm phase-to-phase
#   T-Motor           180 s peak current and power; mass incl. leads
#   KDE Direct        180 s "max continuous" with >= 5 mph airflow;
#                     multirotor motors with a 4 mm bolt-on prop mount -
#                     check the APC adapter
#   SunnySky          10-60 s maximum current; for the V3 X3520/X3525 the
#                     factory's lower RATED figures (the US distributor's
#                     30 s ones are about double)
#   Dualsky           15 s BURST only - no continuous rating published
#   AXI               60 s; the GOLD LINE V3 Ri, which are 0.35-0.6x the
