# The no-load current's test voltage: 10 V unless the source says
# otherwise - Hacker measures at 8.4 V (2S).
for _k, _m in list(MOTORS.items()):
    if "I0 at 8.4 V" in _m.source:
        MOTORS[_k] = replace(_m, i0_volts=8.4)


# ==========================================================================
# Propellers
# ==========================================================================
@dataclass(frozen=True)
class Propeller:
    key: str
    diameter_m: float
    pitch_m: float
    mass_kg: float
    ct0: float              # static thrust coefficient
    cp0: float              # static power coefficient
    j_zero: float           # advance ratio at zero thrust
    kp: float = 0.75        # Cp roll-off: Cp(j_zero) = (1-kp) * cp0
    source: str = "parametric p/D fit - REPLACE with UIUC/APC data"
    # Measured (J, CT, CP), J increasing from 0.  When present the model
    # reads it (monotone cubic between points) instead of the fit above:
    # CT runs linearly to zero at j_zero past the last point, CP continues
    # along its last slope, floored as the fit is.
    table: Tuple[Tuple[float, float, float], ...] = ()
    # The same propeller measured (or computed) at several rpm,
    # ((rpm, table), ...) with rpm rising.  A blade's CT and CP change with
    # rpm - its Reynolds number rises with it - so thrust() and power()
    # read the propeller at the rpm it is turning: linear in rpm between
    # the two nearest levels, the nearest level held outside the range
    # (no extrapolation in Reynolds number).  ct(j) and cp(j) without an
    # rpm read `table`.
    rpm_tables: Tuple[Tuple[float, Tuple[Tuple[float, float, float], ...]], ...] = ()
    # The maker's rpm limit, 0 when none is published (the Aero-naut CAM
    # folding props carry one: prop_rpm_tables.json).  Checked against the
    # motor's no-load speed (PropulsionSystem.rating_check).
    max_rpm: float = 0.0

    def __post_init__(self) -> None:
        if self.rpm_tables:
            rs = [float(r) for r, _t in self.rpm_tables]
            if any(b <= a for a, b in zip(rs, rs[1:])):
                raise ValueError("%s rpm tables: rpm must be strictly increasing"
                                 % self.key)
            object.__setattr__(self, "_lv_rpm", rs)
            object.__setattr__(self, "_lv", [
                _level(self, tuple(tuple(r) for r in t))
                for _r, t in self.rpm_tables])
        if self.table:
            js = [t[0] for t in self.table]
            if any(b <= a for a, b in zip(js, js[1:])):
                raise ValueError("%s table: J must be strictly increasing"
                                 % self.key)
            # A fixed-pitch propeller's CT falls as J rises.  Measured
            # tables wobble - noise, and a static point taken at a different
            # rpm from the tunnel sweep - so CT is made non-increasing by
            # pooling adjacent violators (the least-squares monotone fit).
            # CP is left exactly as measured.
            object.__setattr__(self, "_ct", PCHIP(js, _non_increasing(
                [t[1] for t in self.table])))
            object.__setattr__(self, "_cp", PCHIP(js, [t[2] for t in self.table]))

    @property
    def p_over_d(self) -> float:
        return self.pitch_m / self.diameter_m

    @property
    def measured(self) -> bool:
        return bool(self.table) and "not measured" not in self.source

    @property
    def j_zero_max(self) -> float:
        """The largest zero-thrust advance ratio over the default table and
        every rpm level: past it the propeller makes no thrust at any rpm."""
        if self.rpm_tables:
            return max([self.j_zero] + [lv.j_zero for lv in self._lv])
        return self.j_zero

    @property
    def windmill_drag_coeff(self) -> Optional[float]:
        """Drag of the freewheeling propeller, on disc area, or None when
        there is no table to compute it from.

        With the power cut the propeller spins at the advance ratio where
        its shaft torque is zero, CP(J_w) = 0, and there it makes negative
        thrust.  The tables stop near CT = 0, so both curves are carried
        on by a least-squares line through their last three points:

            D = -CT(J_w) rho n^2 D^4 = -CT rho V^2 D^2 / J_w^2
            Cd (on disc area) = -8 CT(J_w) / (pi J_w^2)

        Zero torque ignores the motor's own drag (bearings, iron loss),
        which slows the propeller and adds a little drag, so this is the
        low side.  Across the catalogue it runs 0.014-0.11 (the lowest on
        the 20x22.5 and 20.5x20.5 high-pitch props).  The props under 8 in,
        removed on 2026-10-04, gave up to 0.54: their short tables made the
        extrapolation to zero torque unreliable.
        """
        pts = list(self.table or ())[-3:]
        if len(pts) < 2:
            return None
        n = float(len(pts))
        jm = sum(p[0] for p in pts) / n
        sjj = sum((p[0] - jm) ** 2 for p in pts)
        if sjj <= 1e-12:
            return None

        def line(k: int) -> Tuple[float, float]:
            ym = sum(p[k] for p in pts) / n
            slope = sum((p[0] - jm) * (p[k] - ym) for p in pts) / sjj
            return ym, slope

        ct_m, s_ct = line(1)
        cp_m, s_cp = line(2)
        if s_cp >= 0.0 or s_ct >= 0.0:
            return None
        j_w = jm - cp_m / s_cp
        ct_w = ct_m + s_ct * (j_w - jm)
        if j_w <= 0.0 or ct_w >= 0.0:
            return None
        return -8.0 * ct_w / (math.pi * j_w * j_w)

    def _at_rpm(self, j: float, rpm: float, thrust: bool) -> float:
        rs, lv = self._lv_rpm, self._lv
        if rpm <= rs[0]:
            return lv[0].ct(j) if thrust else lv[0].cp(j)
        if rpm >= rs[-1]:
            return lv[-1].ct(j) if thrust else lv[-1].cp(j)
        i = bisect.bisect_right(rs, rpm) - 1
        t = (rpm - rs[i]) / (rs[i + 1] - rs[i])
        a, b = lv[i], lv[i + 1]
        if thrust:
            return (1.0 - t) * a.ct(j) + t * b.ct(j)
        return (1.0 - t) * a.cp(j) + t * b.cp(j)

    def ct(self, j: float, rpm: Optional[float] = None) -> float:
        if rpm is not None and self.rpm_tables:
            return self._at_rpm(j, rpm, True)
        if self.table:
            j_last, ct_last = self.table[-1][0], self.table[-1][1]
            if j <= j_last:
                return max(0.0, self._ct(max(j, 0.0)))
            if j >= self.j_zero or self.j_zero <= j_last:
                return 0.0
            return max(0.0, ct_last * (self.j_zero - j) / (self.j_zero - j_last))
        return max(0.0, self.ct0 * (1.0 - j / self.j_zero))

    def cp(self, j: float, rpm: Optional[float] = None) -> float:
        if rpm is not None and self.rpm_tables:
            return self._at_rpm(j, rpm, False)
        if self.table:
            (j1, _, c1), (j2, _, c2) = self.table[-2], self.table[-1]
            if j <= j2:
                return max(0.20 * self.cp0, self._cp(max(j, 0.0)))
            slope = (c2 - c1) / max(j2 - j1, 1e-9)
            return max(0.20 * self.cp0, c2 + slope * (j - j2))
        x = min(j / self.j_zero, 1.25)
        return max(0.20 * self.cp0, self.cp0 * (1.0 - self.kp * x))

    def thrust(self, rho: float, n_rps: float, v: float) -> float:
        if n_rps <= 1e-6:
            return 0.0
        j = v / (n_rps * self.diameter_m)
        return self.ct(j, 60.0 * n_rps) * rho * n_rps ** 2 * self.diameter_m ** 4

    def power(self, rho: float, n_rps: float, v: float) -> float:
        if n_rps <= 1e-6:
            return 0.0
        j = v / (n_rps * self.diameter_m)
        return self.cp(j, 60.0 * n_rps) * rho * n_rps ** 3 * self.diameter_m ** 5


def _table_j_zero(tab) -> float:
    """Zero-thrust advance ratio of a table: its last CT slope carried to
    zero (J 10% past the last point if that slope does not fall)."""
    (j1, c1, _), (j2, c2, _) = tab[-2], tab[-1]
    slope = (c2 - c1) / max(j2 - j1, 1e-9)
    jz = j2 - c2 / slope if slope < -1e-9 else j2 * 1.10
    return max(jz, j2 + 1e-3)


def _level(p: "Propeller", tab) -> "Propeller":
    """One rpm level of a propeller, as a single-table Propeller."""
    return Propeller(key=p.key, diameter_m=p.diameter_m, pitch_m=p.pitch_m,
                     mass_kg=p.mass_kg, ct0=tab[0][1], cp0=tab[0][2],
                     j_zero=_table_j_zero(tab), source=p.source, table=tab)


def _non_increasing(ys):
    """Least-squares non-increasing fit (pool adjacent violators)."""
    blocks = []                      # [mean, count]
    for y in ys:
        blocks.append([y, 1])
        while len(blocks) > 1 and blocks[-2][0] < blocks[-1][0]:
            m2, n2 = blocks.pop()
            m1, n1 = blocks.pop()
            blocks.append([(m1 * n1 + m2 * n2) / (n1 + n2), n1 + n2])
    out = []
    for m, n in blocks:
        out.extend([m] * n)
    return out


def _make_prop(d_in: float, p_in: float) -> Propeller:
    """Parametric APC-thin-electric-like coefficients from pitch/diameter.

    Anchored on three things a real propeller has to satisfy at once:

      * static figure of merit  FOM = ct0^1.5 / (1.2533 cp0)  lands at ~0.71
        for a low-pitch prop falling to ~0.52 for a high-pitch one;
      * peak propulsive efficiency  eta_max = 0.444 * j_zero * ct0/cp0  runs
        ~0.70 (p/D 0.5) to ~0.78 (p/D 0.83);
      * peak efficiency occurs near 0.8x geometric pitch speed, i.e. at
        J/j_zero = 2/3 with the linear Cp roll-off above.

    Check: 13x8 at 8000 rpm gives 7.8 lbf static on 700 W (FOM 0.63), peak
    eta 0.74 at 22 m/s.  Fine for ranking; measure the two or three props you
    shortlist before you trust an absolute number.
    """
    pod = p_in / d_in
    ct0 = 0.115 + 0.030 * pod
    ratio = min(2.70, max(1.40, 2.48 - 2.27 * (pod - 0.50)))
    cp0 = ct0 / ratio
    jz = 1.15 * pod + 0.06
    mass = 0.0009 * (d_in ** 2.2) / 10.0 + 0.012
    return Propeller(key="APC_%gx%g" % (d_in, p_in), diameter_m=d_in * IN2M,
                     pitch_m=p_in * IN2M, mass_kg=mass,
                     ct0=ct0, cp0=cp0, j_zero=jz)


