# The APC Thin Electric props over 21 in (2026-10-02).  No measured data
# exists for them, so each is APC's own computed table (PER3, vortex
# theory) at 4000 rpm - where a 135-220 KV motor turns it - corrected to
# UIUC by the ratio the nearest measured props needed: the five largest
# tested at a comparable Reynolds number (rpm x D^2 >= 1.5M: 18x8, 20x10,
# 18x10, 21x13, 18x12), interpolated in P/D.  Tested on the measured props
# themselves, that predicted peak efficiency within 3% and static figure
# of merit within 2.4%; absolute CT and CP to 10-20%, which moves the
# rpm a prop runs at more than what it does with the power.  APC's 28x20
# 4-blade, the only bigger prop it publishes, is left out: four blades,
# a sport/gas design and no listed weight.
