# High-pitch props around 17-21 in (2026-10-03): the pitch an ideal prop of
# this size wants (P/D 0.75-1.0) where the electric family above 21 in is
# all low pitch.  APC's computed tables again; those inside the measured
# pitch range (P/D <= 0.70, Thin Electric) take the full neighbour
# correction, the rest - higher pitch, or the sport, racing and "CD"
# families - only the loading correction, APC's own efficiency kept, since
# carrying the measured efficiency uplift that far out gave 0.95+, past the
# ideal-propeller limit.  EPN/EP are reverse-rotation versions.  The
# B14x12E/B14x10E are the black 14x12E/14x10E: the same props.
