    # V (<= 100), specific energy 117-179 Wh/kg (LiPo) / 205-233 (Li-ion),
    # IR against capacity, and measured capacity against rated.  Left out:
    # HRB (independent tests delivered 70-85% of rated capacity and 18-23C
    # of a 30-60C label), Dinogy (retailer-only data), ProTek (only a peak
    # C), the CNHL Lightning car pack (its voltages contradict), two Auline
    # packs with no published mass, and two duplicates of packs above.
    # Resistance: the DC figure (a published AC figure x1.7; see
    # r_cell_ohm) where one exists, else the estimate.  The label's C sets
    # the fuse (rule 3.2.3.2d) and the pack-current margin; what limits a
    # pack in flight is its heating (BuildStandard.pack_temp_limit_c).
