PACKS = {p.key: p for p in _PACK_LIST}


def legal_packs(max_wh_total: float, n_systems: int = 1):   # RULE 3.2.3.2b
    """Packs that keep the whole aeroplane inside the energy limit.

    Total propulsion energy is the sum over packs, and every pack must also
    be under the FAA 100 Wh hand-carry limit on its own.
    """
    out = []
    for pk in PACKS.values():
        if pk.watt_hours > 100.0 + 1e-9:
            continue
        if pk.watt_hours * n_systems > max_wh_total + 1e-9:
            continue
        out.append(pk)
    return out


def load_packs_csv(path: str) -> int:
    """Add packs from a CSV with the Catalogues tab's pack columns.

    key, name, chemistry (LiPo, LiHV or LiIon), series, capacity_mah,
    c_rating, mass_g, and optionally max_discharge_a (the label's own
    continuous current), r_cell_mohm, true_mah and v_nom_cell.

    Use this to put your own shortlist in, straight off the labels.
    """
    if not os.path.exists(path):
        return 0
    n = 0
    with open(path, newline="", encoding="utf-8") as fh:
        for row in csv.DictReader(fh):
            PACKS[row["key"]] = _pack_from_row(row)
            n += 1
    return n


# ==========================================================================
# ESC
# ==========================================================================
@dataclass(frozen=True)
class ESC:
    key: str
    i_cont_a: float
    mass_kg: float
    efficiency: float
    max_cells: int
    name: str = ""
    source: str = "generic placeholder - VERIFY"
    min_cells: int = 2
    # What the published continuous rating MEANS: the duration it holds
    # for, the airflow and the ambient it assumes.  Makers rate on very
    # different bases (Scorpion 60 s in a 30-35 m/s stream; KDE 180 s at
    # 5 mph; Castle one pack's worth at 5 mph; Jeti a 2.2 Ah pack), and
    # hardly any means 5 minutes at full throttle in a fuselage.
    rating_s: float = 300.0
    rating_airflow_mps: float = 10.0
    rating_ambient_c: float = 25.0

    def sustained_a(self, duration_s: float, airflow_mps: float,
                    ambient_c: float) -> float:
        """The current this ESC holds for `duration_s` at `airflow_mps`
        over it and `ambient_c`: its published rating moved from its own
        basis to these conditions along the one published derating curve
        (Scorpion Tribunus III manual, section 17), and never above the
        published rating."""
        f_t = min(1.0, _esc_duration_factor(duration_s / 60.0)
                  / _esc_duration_factor(self.rating_s / 60.0))
        f_a = min(1.0, _esc_airflow_factor(airflow_mps)
                  / _esc_airflow_factor(self.rating_airflow_mps))
        f_c = min(1.0, _esc_ambient_factor(ambient_c)
                  / _esc_ambient_factor(self.rating_ambient_c))
        return self.i_cont_a * f_t * f_a * f_c


# The one published ESC derating curve - Scorpion, Tribunus III 14-cell
# manual section 17 - as a share of the 60 s / 30-35 m/s / 30 C rating.
_ESC_DURATION = ((1.0, 1.00), (2.0, 0.82), (5.0, 0.72), (10.0, 0.60))   # min
_ESC_AIRFLOW = ((0.0, 0.50), (5.0, 0.70), (10.0, 0.80), (15.0, 0.87),
                (25.0, 0.95), (32.0, 1.00))                               # m/s
_ESC_AMBIENT = ((30.0, 1.00), (40.0, 0.95), (50.0, 0.87))                 # C


def _esc_duration_factor(t_min: float) -> float:
    """Log-interpolated in time; flat at 1 below 1 min, extended past 10."""
    t = max(t_min, 1e-3)
    pts = _ESC_DURATION
    if t <= pts[0][0]:
        return pts[0][1]
    for (t0, f0), (t1, f1) in zip(pts, pts[1:]):
        if t <= t1:
            return f0 + (f1 - f0) * math.log(t / t0) / math.log(t1 / t0)
    (t0, f0), (t1, f1) = pts[-2], pts[-1]
    return max(0.2, f1 + (f1 - f0) * math.log(t / t1) / math.log(t1 / t0))


def _lin(x: float, pts) -> float:
    if x <= pts[0][0]:
        return pts[0][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x <= x1:
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    (x0, y0), (x1, y1) = pts[-2], pts[-1]
    return y1 + (y1 - y0) * (x - x1) / (x1 - x0)


def _esc_airflow_factor(v: float) -> float:
    return min(1.0, _lin(max(v, 0.0), _ESC_AIRFLOW))


def _esc_ambient_factor(c: float) -> float:
    return max(0.2, _lin(c, _ESC_AMBIENT))


