def pick_esc(current_a: float, cells: int, duration_s: float = 300.0,
             airflow_mps: float = 10.0,
             ambient_c: float = 25.0) -> Optional[ESC]:
    """The LIGHTEST ESC that holds `current_a` (per motor) with 20 percent
    headroom for `duration_s` at `airflow_mps` and `ambient_c`
    (ESC.sustained_a), and supports the cell count."""
    need = current_a * 1.20
    best = None
    for e in ESCS.values():
        if (e.min_cells <= cells <= e.max_cells
                and e.sustained_a(duration_s, airflow_mps, ambient_c) >= need):
            if best is None or (e.mass_kg, e.i_cont_a) < (best.mass_kg,
                                                          best.i_cont_a):
                best = e
    return best


